-- regions seed (nationwide hangjeongdong centroids)
-- source: vuski/admdongkor HangJeongDong_ver20260401.geojson (WGS84)
-- region_code = adm_cd2 (10-digit), safe re-run with upsert
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS regions (
  region_code BIGINT NOT NULL,
  region_name VARCHAR(100) NOT NULL,
  center_latitude DECIMAL(10,7) NOT NULL,
  center_longitude DECIMAL(10,7) NOT NULL,
  PRIMARY KEY (region_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE region_name = VALUES(region_name), center_latitude = VALUES(center_latitude), center_longitude = VALUES(center_longitude);

